#!/usr/bin/env bash
# fresh-clone: anonymous public clone of this repo at a commit, then every offline internals check: sha256 of the key
# files compared with the hashes the recorded install log printed, shellcheck, ruff (both working directories), the
# unit suite, the promtool rule tests (regenerated byte-identically first), the calibration stats re-derived from the
# committed data, and the byte-identical rebuild (`cmp` exit 0) of the published 24-hour report from its committed
# query capture. Nothing on the host is read or changed (promtool runs with --network none).
#   bash internals/drill/fresh-clone.sh SHA INSTALL_LOG [--mutants] 2>&1 | tee LOG
#   INSTALL_LOG: repo path of the recorded install log, e.g. internals/logs/03-install.log
# --mutants also runs tests/mutate.py. The work dir is a new mktemp dir under ~/.cache, mode 755 (/tmp is noexec
# here, and the promtool container runs as nobody), removed at the end.
set -uo pipefail
SHA="${1:?usage: fresh-clone.sh SHA INSTALL_LOG [--mutants]}"
ILOG="${2:?usage: fresh-clone.sh SHA INSTALL_LOG [--mutants]}"
MUT=0; [ "${3:-}" = --mutants ] && MUT=1
export TZ=UTC
W="$(mktemp -d -p "$HOME/.cache")"; chmod 755 "$W"; trap 'rm -rf "$W"' EXIT
red() { sed -u -E "s#$HOME#~#g; s#\b$(id -un)\b#<user>#g"; }
x() { echo "\$ $*" | red; ( eval "$*" ) 2>&1 | red; rc=${PIPESTATUS[0]}; echo "(exit $rc)"; return "$rc"; }
FAILS=0; must() { x "$@" || FAILS=$((FAILS + 1)); }
KEY="internals/pft-internals.sh internals/internals_parse.py internals/systemd/pft-internals@.service internals/systemd/pft-internals@.timer internals/systemd/pft-internals-pull@.service internals/systemd/pft-internals-pull@.timer alerts/internals.rules.yml"
echo "OS: $(lsb_release -ds) | $(date -u +%FT%TZ) | internals fresh-clone verification at $SHA | $(shellcheck --version | sed -n 's/^version: /shellcheck /p') | $(python3 --version) | ruff $(ruff --version | cut -d' ' -f2)"
echo "(work dir: a new mktemp dir under ~/.cache, mode 755; /tmp is noexec on this host)"
cd "$W" || exit 3
must "env -u GH_TOKEN -u GITHUB_TOKEN GIT_TERMINAL_PROMPT=0 git -c credential.helper= clone -q https://github.com/darkmatter-sudo/postfiat-validator-installer.git repo"
cd repo || exit 3
must "git checkout -q $SHA && git rev-parse HEAD"
must "test \"\$(git status --short | wc -l)\" = 0 && echo clean"
echo "== key files: sha256 here vs. the hashes the recorded install printed ($ILOG)"
must "sha256sum $KEY"
must "test -f $ILOG && grep -cE '^  [0-9a-f]{64}  (internals|alerts)/' $ILOG"
must "for f in $KEY; do want=\$(grep -E \"^  [0-9a-f]{64}  \$f\\\$\" $ILOG | head -1 | awk '{print \$1}'); got=\$(sha256sum \$f | cut -c1-64); [ -n \"\$want\" ] && [ \"\$want\" = \"\$got\" ] && echo \"MATCH \$f\" || { echo \"MISMATCH \$f install=\${want:-none} clone=\$got\"; exit 1; }; done"
must "sha256sum internals/logs/*.log internals/data/* internals/logs/report-24h/*"
echo "== static checks"
must "shellcheck internals/*.sh internals/drill/*.sh"
must "ruff check internals && ruff format --check internals"
must "cd internals && ruff check . && ruff format --check ."
echo "== unit suite (parser, shell with docker/ssh stubs, report)"
must "TMPDIR=$W TEST_TMPDIR=$W python3 -I internals/tests/test_internals.py 2>&1 | tail -n 3"
echo "== promtool"
must "python3 internals/tests/gen_rule_tests.py | cmp - alerts/internals.tests.yml && echo identical internals.tests.yml"
must "docker run --rm --network none --entrypoint promtool -v \"\$PWD/alerts\":/w:ro -w /w prom/prometheus:v3.5.0 check rules internals.rules.yml"
must "docker run --rm --network none --entrypoint promtool -v \"\$PWD/alerts\":/w:ro -w /w prom/prometheus:v3.5.0 test rules internals.tests.yml"
echo "== calibration stats re-derived from the committed data"
must "python3 -I internals/tests/calib_stats.py stats internals/data/calibration-validator.jsonl | cmp - <(sed -n '3,7p' internals/logs/01-calibration.log) && echo identical calibration stats"
echo "== byte-identical rebuild of the published 24-hour report from its committed query capture"
must "python3 -I internals/report_internals.py build internals/logs/report-24h/capture.json --md $W/report.md --json $W/report.json"
must "cmp $W/report.md internals/logs/report-24h/report.md && echo identical report.md"
must "cmp $W/report.json internals/logs/report-24h/report.json && echo identical report.json"
if [ "$MUT" = 1 ]; then
  echo "== mutation harness"
  must "TEST_TMPDIR=$W nice -n 15 python3 -u internals/tests/mutate.py </dev/null | tail -n 6"
fi
echo "fresh-clone done $(date -u +%FT%TZ): $FAILS step(s) failed -> $([ "$FAILS" = 0 ] && echo PASS || echo FAIL)"
[ "$FAILS" = 0 ]
